// TestRouteStatusOverridesJSONStable snapshots the JSON envelope shape so
// downstream operator tooling (dashboards, alerts) can rely on it. New
// keys may be added behind a flag — never silently changed.
func TestRouteStatusOverridesJSONStable(t *testing.T) {
	start := time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC)
	end := time.Date(2026, 4, 25, 0, 0, 0, 0, time.UTC)
	envelope := routeStatusOverridesOutput{
		Since:                    "168h",
		WindowStart:              start,
		WindowEnd:                end,
		AxisFilter:               "harness",
		AutoAcceptanceRate:       0.4,
		OverrideDisagreementRate: 0.5,
		TotalRequests:            5,
		TotalOverrides:           3,
		OverrideClassBreakdown: []fizeau.OverrideClassBucket{
			{
				PromptFeatureBucket: "tokens=small,tools=no,reasoning=none",
				Axis:                "harness",
				Match:               false,
				Count:               2,
				SuccessOutcomes:     1,
				FailedOutcomes:      1,
			},
		},
	}

	var buf bytes.Buffer
	writeRouteStatusOverridesJSON(&buf, envelope)

	// Round-trip parse: schema must decode into a known shape, with every
	// AC-required key present at the top level.
	var generic map[string]json.RawMessage
	if err := json.Unmarshal(buf.Bytes(), &generic); err != nil {
		t.Fatalf("unmarshal: %v\n%s", err, buf.String())
	}
	requiredTopLevel := []string{
		"since",
		"window_start",
		"window_end",
		"axis_filter",
		"auto_acceptance_rate",
		"override_disagreement_rate",
		"total_requests",
		"total_overrides",
		"override_class_breakdown",
	}
	for _, k := range requiredTopLevel {
		if _, ok := generic[k]; !ok {
			t.Errorf("required key %q missing from JSON envelope:\n%s", k, buf.String())
		}
	}

	// Bucket schema: every documented field must round-trip.
	var bkt []fizeau.OverrideClassBucket
	if err := json.Unmarshal(generic["override_class_breakdown"], &bkt); err != nil {
		t.Fatalf("decode breakdown: %v", err)
	}
	if len(bkt) != 1 {
		t.Fatalf("breakdown len = %d, want 1", len(bkt))
	}
	got := bkt[0]
	if got.PromptFeatureBucket != "tokens=small,tools=no,reasoning=none" {
		t.Errorf("PromptFeatureBucket = %q", got.PromptFeatureBucket)
	}
	if got.Axis != "harness" || got.Match != false || got.Count != 2 {
		t.Errorf("bucket fields lost in round-trip: %+v", got)
	}
	if got.SuccessOutcomes != 1 || got.FailedOutcomes != 1 {
		t.Errorf("outcome aggregates lost in round-trip: %+v", got)
	}

	// Verify the bucket JSON keys themselves are stable: per ADR-006 §5
	// the breakdown is the operator pivot, so its key names are part of
	// the contract.
	var bucketGeneric []map[string]json.RawMessage
	if err := json.Unmarshal(generic["override_class_breakdown"], &bucketGeneric); err != nil {
		t.Fatalf("decode bucket generic: %v", err)
	}
	requiredBucketKeys := []string{
		"prompt_feature_bucket",
		"axis",
		"match",
		"count",
		"success_outcomes",
		"stalled_outcomes",
		"failed_outcomes",
		"cancelled_outcomes",
		"unknown_outcomes",
	}
	for _, k := range requiredBucketKeys {
		if _, ok := bucketGeneric[0][k]; !ok {
			t.Errorf("bucket key %q missing:\n%s", k, buf.String())
		}
	}

	// Snapshot the JSON output; trailing newline tolerated.
	want := `{
  "since": "168h",
  "window_start": "2026-04-18T00:00:00Z",
  "window_end": "2026-04-25T00:00:00Z",
  "axis_filter": "harness",
  "auto_acceptance_rate": 0.4,
  "override_disagreement_rate": 0.5,
  "total_requests": 5,
  "total_overrides": 3,
  "override_class_breakdown": [
    {
      "prompt_feature_bucket": "tokens=small,tools=no,reasoning=none",
      "axis": "harness",
      "match": false,
      "count": 2,
      "success_outcomes": 1,
      "stalled_outcomes": 0,
      "failed_outcomes": 1,
      "cancelled_outcomes": 0,
      "unknown_outcomes": 0
    }
  ]
}
`
	if got := buf.String(); got != want {
		t.Errorf("JSON envelope drift.\n--- got ---\n%s\n--- want ---\n%s", got, want)
	}

	// Empty axis_filter must omit the field (omitempty contract).
	envelope.AxisFilter = ""
	buf.Reset()
	writeRouteStatusOverridesJSON(&buf, envelope)
	if strings.Contains(buf.String(), `"axis_filter"`) {
		t.Errorf("empty axis_filter should be omitted (omitempty):\n%s", buf.String())
	}
}

	default:
		return fmt.Errorf("invalid CachePolicy %q: want \"\", %q, or %q", v, CachePolicyDefault, CachePolicyOff)
	}
}

// ValidatePowerBounds returns nil when the optional numeric routing power
// bounds are unset or coherent. Zero means "unset"; positive values are on
// the catalog's 1-10 power scale.
func ValidatePowerBounds(minPower, maxPower int) error {
	if minPower < 0 {
		return fmt.Errorf("invalid MinPower %d: must be >= 0", minPower)
	}
	if maxPower < 0 {
		return fmt.Errorf("invalid MaxPower %d: must be >= 0", maxPower)
	}
	if minPower > 0 && maxPower > 0 && maxPower < minPower {
		return fmt.Errorf("invalid power bounds: MaxPower %d must be >= MinPower %d", maxPower, minPower)
	}
	return nil
}

// RouteDecision is the result of ResolveRoute.
type RouteDecision struct {
	// Harness is the selected harness name.
	Harness string
	// Provider is the selected provider for native agent routes.
	Provider string
	// Endpoint is the selected named endpoint when the provider exposes more
	// than one endpoint.
	Endpoint string
	// Model is the selected concrete model.
	Model string
	// Reason summarizes why the selected candidate won.
	Reason string
	// Power is the catalog-projected power of the selected Model
	// (per CONTRACT-003 § Catalog Power Projection). 0 means
	// unknown/exact-pin-only/no catalog entry. DDx callers read this
	// to compute next-attempt MinPower without importing catalog code.
	Power int
	// Candidates is the full ranked decision trace, including rejected
	// candidates and their rejection reasons.
	Candidates []RouteCandidate
}

// RouteCandidate is one routing candidate evaluated by ResolveRoute.
type RouteCandidate struct {
	// Harness is the candidate harness name.
	Harness string
	// Provider is the candidate provider name for native agent routes.
	Provider string
	// Endpoint is the provider endpoint name when applicable.
	Endpoint string
	// Model is the candidate concrete model.
	Model string
	// Score is the routing score assigned before final ordering.
	Score float64
	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	CostUSDPer1kTokens float64
	// CostSource indicates whether cost came from catalog, subscription,
	// user-config, or is unknown.
	CostSource string
	// Eligible reports whether the candidate passed all routing gates.
	Eligible bool
	// Reason is the scoring reason for eligible candidates or the rejection
	// reason for ineligible candidates.
	Reason string
	// FilterReason names the gate that disqualified an ineligible candidate.
	// Empty when Eligible. See the FilterReason* constants.
	FilterReason string
	// Components carries the per-axis score inputs (power, cost, latency,
	// success rate, quota, capability) that fed the final Score. Consumers use these to
	// explain rankings without parsing the free-form Reason.
	Components RouteCandidateComponents
}

// FilterReason* enumerate the canonical disqualification reasons surfaced
// in RouteCandidate.FilterReason and the routing-decision event.
const (
	FilterReasonUnhealthy            = "unhealthy"
	FilterReasonContextTooSmall      = "context_too_small"
	FilterReasonNoToolSupport        = "no_tool_support"
	FilterReasonReasoningUnsupported = "reasoning_unsupported"
	FilterReasonScoredBelowTop       = "scored_below_top"
)

// RouteCandidateComponents breaks down the inputs that fed a candidate's
// final Score so consumers can explain rankings without parsing the
// free-form Reason. Zero fields mean "unknown / not contributing".
type RouteCandidateComponents struct {
	// Power is the catalog model power used by automatic routing. Zero means
	// unknown or not contributing.
	Power int
	// Cost is the per-1k-token cost expressed as a numeric component (USD).
	// Mirrors RouteCandidate.CostUSDPer1kTokens; surfaced here so the event
	// payload carries a single component bundle.
	Cost float64
	// CostClass is the candidate cost class used by the router.
	CostClass string
	// LatencyMS is the observed median latency for this candidate, in
	// milliseconds. Zero when no observations are available.
	LatencyMS float64
	// SpeedTPS is the observed output speed in tokens per second. Zero when
	// no observations are available.
	SpeedTPS float64
	// SuccessRate is the observed success rate (0–1) for this candidate.
	// Negative means insufficient data; zero means unknown.
	SuccessRate float64
	// QuotaOK/QuotaPercentUsed/QuotaTrend are subscription quota inputs used
	// by routing. They are zero values for non-subscription candidates.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaTrend       string
	// Capability is a coarse capability score derived from the candidate's
	// cost class / surface (higher = more capable).
	Capability float64
}

// RouteAttempt is caller feedback about one attempted route candidate.
// Status="success" clears matching active failures; any other non-empty status
// records a same-process failure until the service health cooldown expires.
type RouteAttempt struct {
	Harness   string
	Provider  string
	Model     string
	Endpoint  string
	Status    string
	Reason    string
	Error     string
	Duration  time.Duration
	Timestamp time.Time // zero = time.Now()
}

// RouteStatusReport is returned by RouteStatus.
//
// RoutingQuality (ADR-006 §5) is the operator-facing measure of how often
// auto-routing produces an acceptable decision. It is intentionally
// distinct from per-(provider, model) provider-reliability surfaced on
// each RouteCandidateStatus: the two compose, and conflating them is the
// UI bug ADR-006 fixes.
type RouteStatusReport struct {
	Routes          []RouteStatusEntry
	GeneratedAt     time.Time
	GlobalCooldowns []CooldownState
	// RoutingQuality holds the three first-class routing-quality metrics
	// over a recent window (last RouteStatusRoutingQualityWindow requests).
	RoutingQuality RoutingQualityMetrics
}

// RouteStatusRoutingQualityWindow caps how many recent Execute calls
// contribute to RouteStatusReport.RoutingQuality. ADR-006 §5 calls for a
// "recent window"; the constant is exported so operator UIs can label the
// metric appropriately.
const RouteStatusRoutingQualityWindow = 100

// RouteStatusEntry describes the live provider candidates serving one model.
type RouteStatusEntry struct {
	Model          string
	Strategy       string // informational; route tables are not user-authored
	Candidates     []RouteCandidateStatus
	LastDecision   *RouteDecision // most recent ResolveRoute result for this key (cached)
	LastDecisionAt time.Time
}

// RouteCandidateStatus describes a single live provider/model candidate.
//
// ProviderReliabilityRate is the per-(provider, model) observed completion
// rate (the legacy "success rate" metric). Per ADR-006 §5 it is labeled
// "provider reliability" to distinguish it from RoutingQualityMetrics on
// the parent report — the two metrics measure different things and are
// surfaced as separate fields.
type RouteCandidateStatus struct {
	Provider                string
	Model                   string
	Priority                int
	Healthy                 bool
	Cooldown                *CooldownState
	RecentLatencyMS         float64 // observation-derived; 0 when unavailable
	ProviderReliabilityRate float64 // 0-1; 0 when unavailable. Legacy success-rate field, relabeled per ADR-006 §5 to disambiguate from routing-quality.
}

// ServiceEvent is a contract-level event (mirrors harnesses.Event).
type ServiceEvent = harnesses.Event

// ServiceExecuteRequest is the public ExecuteRequest type per CONTRACT-003.
// See docs/helix/02-design/contracts/CONTRACT-003-fizeau-service.md
// (§"Public types") for the canonical shape; this struct is its in-process
// twin under the agent module.
type ServiceExecuteRequest struct {
	Prompt            string
	SystemPrompt      string
	Model             string
	Provider          string
	Harness           string
	ModelRef          string
	Profile           string
	WorkDir           string
	Temperature       *float32
	TopP              *float64
	TopK              *int
	MinP              *float64
	RepetitionPenalty *float64
	Seed              *int64
	// SamplingSource is the comma-separated layer attribution produced by
	// internal/sampling.Resolve. Plumbed through to the llm.request
	// telemetry event for ADR-007 override-tracking; never on the wire.
	SamplingSource string
	Reasoning      Reasoning
	NoStream       bool
	Permissions    string
	// Tools overrides the built-in native agent tool set when Harness is
	// "agent". Nil uses the native built-ins for ToolPreset and WorkDir.
	Tools []Tool
	// ToolPreset is passed through to BuiltinToolsForPreset when Tools is nil.
	// Empty uses the default tool set.
	ToolPreset string

	// PlanningMode, when true, performs one no-tool LLM "planning" call
	// before the main native agent loop and injects the response as an
	// assistant message wrapped in <plan> tags. The benchmark tool preset
	// auto-enables planning; this flag is the per-request opt-in for other
	// callers (e.g. the CLI --plan flag). Only honored when Harness=="agent"
	// (the native loop). See internal/core.Request.PlanningMode.
	PlanningMode bool

	// EstimatedPromptTokens, when > 0, drives auto-selection's
	// context-window gate (filter out candidates whose context window is
	// too small for the prompt + safety margin).
	EstimatedPromptTokens int
	// RequiresTools, when true, drives auto-selection's tool-support gate
	// (filter out candidates that cannot invoke tools).
	RequiresTools bool
	MinPower      int
	MaxPower      int

	// CachePolicy is the public opt-out for prompt caching. Empty (the zero
	// value) and "default" both request the per-provider default caching
	// behavior; "off" disables caching for this request. Any other value is
	// rejected at the service boundary (see ValidateCachePolicy). Providers
	// that do not implement caching ignore the field; this field is read by
	// the Anthropic cache_control writer (bead C) and the cache-aware cost
	// attribution path (bead D).

package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) routeUtilizationStore() *routehealth.UtilizationStore {
	if s.routeUtilization == nil {
		s.routeUtilization = routehealth.NewUtilizationStore()
	}
	return s.routeUtilization
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	if decision.Harness != "agent" || decision.Provider == "" {
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
	if lease, ok := store.Live(now, key); ok {
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
			store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
			decision.Provider = candidate.Provider
			decision.Endpoint = candidate.Endpoint
			return
		}
		reason := "endpoint disappeared"
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		}
		store.Invalidate(now, key, reason)
	}
	if decision.Provider == "" && decision.Endpoint == "" {
		return
	}
	chosenEndpoint := decision.Endpoint
	if chosenEndpoint == "" {
		_, chosenEndpoint, _ = splitEndpointProviderRef(decision.Provider)
	}
	if chosenEndpoint == "" {
		chosenEndpoint = decision.Provider
	}
	if chosenEndpoint == "" {
		return
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
}

func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if candidate.Harness != harness {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func (s *service) routeEndpointLoadsResolver(now time.Time) func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
	if s == nil {
		return nil
	}
	leaseStore := s.routeLeaseStore()
	utilStore := s.routeUtilizationStore()
	return func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
		leaseCounts := leaseStore.LeaseCounts(now, provider, model)
		loads := utilStore.EndpointLoads(provider, model, leaseCounts)
		load, ok := loads[endpoint]
		if !ok {
			if count, ok := leaseCounts[endpoint]; ok {
				return routing.EndpointLoad{
					LeaseCount:       count,
					NormalizedLoad:   float64(count),
					UtilizationFresh: false,
				}, true
			}
			return routing.EndpointLoad{}, false
		}
		return routing.EndpointLoad{
			LeaseCount:           load.LeaseCount,
			NormalizedLoad:       load.NormalizedLoad,
			UtilizationFresh:     load.UtilizationFresh,
			UtilizationSaturated: load.UtilizationSaturated,
		}, true
	}
}

package utilization

import (
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Source identifies the probe path that produced a utilization sample.
type Source string

const (
	SourceUnknown        Source = "unknown"
	SourceOMLXStatus     Source = "omlx.status"
	SourceVLLMMetrics    Source = "vllm.metrics"
	SourceLlamaMetrics   Source = "llama-server.metrics"
	SourceLlamaSlots     Source = "llama-server.slots"
	SourceRapidMLXStatus Source = "rapid-mlx.status"
)

// Freshness describes whether a sample was observed just now, reused after a
// failed probe, or has no known prior observation.
type Freshness string

const (
	FreshnessFresh   Freshness = "fresh"
	FreshnessStale   Freshness = "stale"
	FreshnessUnknown Freshness = "unknown"
)

// EndpointUtilization is the normalized utilization shape shared by local
// provider probes.
type EndpointUtilization struct {
	ActiveRequests         *int
	QueuedRequests         *int
	CacheUsage             *float64
	MaxConcurrency         *int
	TotalPromptTokens      *int
	TotalCompletionTokens  *int
	CacheHitType           *string
	CachedTokens           *int
	GeneratedTokens        *int
	ActiveRequestPhase     *string
	TTFTSeconds            *float64
	TokensPerSecond        *float64
	MetalActiveMemoryBytes *int64
	MetalPeakMemoryBytes   *int64
	MetalCacheMemoryBytes  *int64
	Source                 Source
	Freshness              Freshness
	ObservedAt             time.Time
}

// Cache preserves the most recent successful sample so probe failures can
// return stale utilization instead of surfacing hard endpoint unavailability.
type Cache struct {
	mu   sync.Mutex
	last *EndpointUtilization
}

// Remember stores a fresh sample and returns a normalized copy with fresh
// freshness and an observed timestamp.
func (c *Cache) Remember(sample EndpointUtilization) EndpointUtilization {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now().UTC()
	sample.Freshness = FreshnessFresh
	sample.ObservedAt = now
	stored := clone(sample)
	c.last = &stored
	return stored
}

// Stale returns the last successful sample marked stale. The boolean reports
// whether a previous sample existed.
func (c *Cache) Stale() (EndpointUtilization, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.last == nil {
		return EndpointUtilization{}, false
	}
	stale := clone(*c.last)
	stale.Freshness = FreshnessStale
	return stale, true
}

// Unknown returns a sample with unknown freshness and no numeric values.
func Unknown(source Source) EndpointUtilization {
	return EndpointUtilization{
		Source:    source,
		Freshness: FreshnessUnknown,
	}
}

// Int returns a pointer to v.
func Int(v int) *int {
	return &v
}

// Float64 returns a pointer to v.
func Float64(v float64) *float64 {
	return &v
}

// Int64 returns a pointer to v.
func Int64(v int64) *int64 {
	return &v
}

// String returns a pointer to v.
func String(v string) *string {
	return &v
}

// ServerRoot strips a trailing /v1 path component from an OpenAI-compatible
// base URL while preserving the scheme, host, and any prefix path.
func ServerRoot(baseURL string) string {
	trimmed := strings.TrimSpace(strings.TrimRight(baseURL, "/"))
	if trimmed == "" {
		return ""
	}

	parsed, err := url.Parse(trimmed)
	if err != nil {
		return strings.TrimSuffix(trimmed, "/v1")
	}

	parsed.Fragment = ""
	parsed.RawQuery = ""
	path := strings.TrimRight(parsed.Path, "/")
	if strings.HasSuffix(path, "/v1") {
		path = strings.TrimSuffix(path, "/v1")
	}
	parsed.Path = path
	return strings.TrimRight(parsed.String(), "/")
}

// ParsePrometheusMetricValue returns the first numeric value for metric from
// a Prometheus-style plaintext metrics body.
func ParsePrometheusMetricValue(body, metric string) (float64, bool) {
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || !strings.HasPrefix(line, metric) {
			continue
		}
		rest := strings.TrimSpace(strings.TrimPrefix(line, metric))
		if strings.HasPrefix(rest, "{") {
			if idx := strings.Index(rest, "}"); idx >= 0 {
				rest = strings.TrimSpace(rest[idx+1:])
			}
		}
		fields := strings.Fields(rest)
		if len(fields) == 0 {
			continue
		}
		val, err := strconv.ParseFloat(fields[0], 64)
		if err == nil {
			return val, true
		}
	}
	return 0, false
}

func clone(sample EndpointUtilization) EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = Int(*sample.MaxConcurrency)
	}
	if sample.TotalPromptTokens != nil {
		out.TotalPromptTokens = Int(*sample.TotalPromptTokens)
	}
	if sample.TotalCompletionTokens != nil {
		out.TotalCompletionTokens = Int(*sample.TotalCompletionTokens)
	}
	if sample.CacheHitType != nil {
		out.CacheHitType = String(*sample.CacheHitType)
	}
	if sample.CachedTokens != nil {
		out.CachedTokens = Int(*sample.CachedTokens)
	}
	if sample.GeneratedTokens != nil {
		out.GeneratedTokens = Int(*sample.GeneratedTokens)
	}
	if sample.ActiveRequestPhase != nil {
		out.ActiveRequestPhase = String(*sample.ActiveRequestPhase)
	}
	if sample.TTFTSeconds != nil {
		out.TTFTSeconds = Float64(*sample.TTFTSeconds)
	}
	if sample.TokensPerSecond != nil {
		out.TokensPerSecond = Float64(*sample.TokensPerSecond)
	}
	if sample.MetalActiveMemoryBytes != nil {
		out.MetalActiveMemoryBytes = Int64(*sample.MetalActiveMemoryBytes)
	}
	if sample.MetalPeakMemoryBytes != nil {
		out.MetalPeakMemoryBytes = Int64(*sample.MetalPeakMemoryBytes)
	}
	if sample.MetalCacheMemoryBytes != nil {
		out.MetalCacheMemoryBytes = Int64(*sample.MetalCacheMemoryBytes)
	}
	return out
}

package routehealth

import (
	"sort"
	"strings"
	"sync"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationKey identifies one provider endpoint/model utilization sample.
type UtilizationKey struct {
	Provider string
	Endpoint string
	Model    string
}

// EndpointLoad is the normalized load signal used by routing.
type EndpointLoad struct {
	LeaseCount           int
	NormalizedLoad       float64
	UtilizationFresh     bool
	UtilizationSaturated bool
}

// UtilizationStore retains the most recent utilization sample for each
// provider endpoint. It is safe for concurrent use.
type UtilizationStore struct {
	mu      sync.RWMutex
	samples map[UtilizationKey]utilization.EndpointUtilization
}

// NewUtilizationStore returns an empty utilization store.
func NewUtilizationStore() *UtilizationStore {
	return &UtilizationStore{
		samples: make(map[UtilizationKey]utilization.EndpointUtilization),
	}
}

// NormalizeUtilizationKey trims whitespace from the utilization dimensions.
func NormalizeUtilizationKey(provider, endpoint, model string) UtilizationKey {
	return UtilizationKey{
		Provider: strings.TrimSpace(provider),
		Endpoint: strings.TrimSpace(endpoint),
		Model:    strings.TrimSpace(model),
	}
}

// Record stores the latest utilization sample for key.
func (s *UtilizationStore) Record(provider, endpoint, model string, sample utilization.EndpointUtilization) {
	if s == nil {
		return
	}
	key := NormalizeUtilizationKey(provider, endpoint, model)
	if key.Provider == "" && key.Endpoint == "" && key.Model == "" {
		return
	}
	if sample.Freshness == "" {
		sample.Freshness = utilization.FreshnessFresh
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.samples == nil {
		s.samples = make(map[UtilizationKey]utilization.EndpointUtilization)
	}
	s.samples[key] = cloneUtilization(sample)
}

// EndpointLoads returns the normalized load per endpoint for provider/model.
// Fresh utilization samples are combined with the supplied lease counts;
// stale or missing samples fall back to lease counts only.
func (s *UtilizationStore) EndpointLoads(provider, model string, leaseCounts map[string]int) map[string]EndpointLoad {
	if s == nil {
		return nil
	}
	keyProvider := strings.TrimSpace(provider)
	keyModel := strings.TrimSpace(model)

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.samples) == 0 && len(leaseCounts) == 0 {
		return nil
	}

	keys := make(map[string]struct{})
	for endpoint := range leaseCounts {
		keys[endpoint] = struct{}{}
	}
	for key := range s.samples {
		if keyProvider != "" && key.Provider != keyProvider {
			continue
		}
		if keyModel != "" && key.Model != keyModel {
			continue
		}
		if key.Endpoint != "" {
			keys[key.Endpoint] = struct{}{}
		}
	}
	if len(keys) == 0 {
		return nil
	}

	out := make(map[string]EndpointLoad, len(keys))
	for endpoint := range keys {
		leaseCount := leaseCounts[endpoint]
		load := EndpointLoad{
			LeaseCount:       leaseCount,
			NormalizedLoad:   float64(leaseCount),
			UtilizationFresh: false,
		}
		key := NormalizeUtilizationKey(keyProvider, endpoint, keyModel)
		sample, ok := s.samples[key]
		if !ok && keyProvider != "" {
			// Allow provider-wide samples to match when the caller does not
			// have a fully-qualified endpoint name.
			sample, ok = s.samples[NormalizeUtilizationKey(keyProvider, "", keyModel)]
		}
		if !ok || sample.Freshness != utilization.FreshnessFresh {
			out[endpoint] = load
			continue
		}
		normalized, saturated := normalizedLoadFromSample(sample)
		load.NormalizedLoad = float64(leaseCount) + normalized
		load.UtilizationFresh = true
		load.UtilizationSaturated = saturated
		out[endpoint] = load
	}

	return out
}

func normalizedLoadFromSample(sample utilization.EndpointUtilization) (float64, bool) {
	var active int
	var queued int
	if sample.ActiveRequests != nil {
		active = *sample.ActiveRequests
	}
	if sample.QueuedRequests != nil {
		queued = *sample.QueuedRequests
	}
	if sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := active + queued
		pressure := float64(total) / float64(*sample.MaxConcurrency)
		if pressure < 0 {
			pressure = 0
		}
		return pressure, total >= *sample.MaxConcurrency
	}
	if sample.CacheUsage != nil {
		pressure := *sample.CacheUsage
		if pressure < 0 {
			pressure = 0
		}
		return pressure, pressure >= 1
	}
	total := active + queued
	if total < 0 {
		total = 0
	}
	return float64(total), false
}

func cloneUtilization(sample utilization.EndpointUtilization) utilization.EndpointUtilization {
	out := sample
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.CacheUsage != nil {
		out.CacheUsage = utilization.Float64(*sample.CacheUsage)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	return out
}

// EndpointLoadList returns a deterministic endpoint ordering for tests.
func EndpointLoadList(loads map[string]EndpointLoad) []string {
	if len(loads) == 0 {
		return nil
	}
	out := make([]string, 0, len(loads))
	for endpoint := range loads {
		out = append(out, endpoint)
	}
	sort.Strings(out)
	return out
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// agent-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	if profile == "" {
		profile = reqProfileFromModelRef(cat, req.ModelRef)
	}
	modelRef := reqModelRefStripProfile(cat, req.ModelRef)
	providerPreference, err := providerPreferenceForProfile(cat, profile)
	if err != nil {
		return &RouteDecision{}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	rReq := routing.Request{
		Profile:               profile,
		ModelRef:              modelRef,
		Model:                 req.Model,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		MinPower:              req.MinPower,
		MaxPower:              req.MaxPower,
	}
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		return result, publicRoutingError(err, result.Candidates)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:    dec.Harness,
		Provider:   dec.Provider,
		Endpoint:   dec.Endpoint,
		Model:      dec.Model,
		Reason:     dec.Reason,
		Candidates: routeCandidatesFromInternal(dec.Candidates),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Endpoint:           candidate.Endpoint,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		Components: RouteCandidateComponents{
			Power:            candidate.Power,
			Cost:             candidate.CostUSDPer1kTokens,
			CostClass:        candidate.CostClass,
			LatencyMS:        candidate.LatencyMS,
			SpeedTPS:         candidate.SpeedTPS,
			SuccessRate:      candidate.SuccessRate,
			QuotaOK:          candidate.QuotaOK,
			QuotaPercentUsed: candidate.QuotaPercentUsed,
			QuotaTrend:       candidate.QuotaTrend,
			Capability:       capabilityScoreForCostClass(candidate.CostClass),
		},
	}
}

// publicFilterReason maps the typed FilterReason emitted by the internal
// routing engine to the public FilterReason* string constant. The internal
// constants are defined to share string values with the public surface, so
// this is a one-line passthrough — there is no string parsing.
func publicFilterReason(c routing.Candidate) string {
	if c.Eligible {
		return ""
	}
	return string(c.FilterReason)
}

// capabilityScoreForCostClass maps the harness cost class to a coarse
// numeric capability proxy. Mirrors the engine's costClassRank ordering
// (more expensive ≈ more capable) for reporting purposes only.
func capabilityScoreForCostClass(class string) float64 {
	switch class {
	case "local":
		return 0
	case "cheap":
		return 1
	case "medium", "":
		return 2
	case "expensive":
		return 3
	case "experimental":
		return -1
	default:
		return 0
	}
}

// escalateProfileLadder walks routing.ProfileEscalationLadder when Resolve
// returns a "no eligible candidate" error and the request's profile is in
// the ladder. Returns (true, decision, nil) when a higher tier resolves to
// an eligible candidate, or (true, nil, *routing.ErrNoLiveProvider) when
// the entire remaining ladder is also empty. Returns (false, _, _) when
// escalation does not apply (hard pin error, profile not in ladder, etc.).
func escalateProfileLadder(req routing.Request, in routing.Inputs, origErr error) (bool, *routing.Decision, error) {
	if origErr == nil || req.Profile == "" {
		return false, nil, nil
	}
	if !shouldEscalateOnError(origErr) {
		return false, nil, nil
	}
	startIdx := -1
	for i, p := range routing.ProfileEscalationLadder {
		if p == req.Profile {
			startIdx = i
			break
		}
	}
	if startIdx < 0 {
		return false, nil, nil
	}
	for i := startIdx + 1; i < len(routing.ProfileEscalationLadder); i++ {
		probe := req
		probe.Profile = routing.ProfileEscalationLadder[i]
		dec, err := routing.Resolve(probe, in)
		if err == nil && dec != nil && dec.Harness != "" {
			return true, dec, nil
		}
	}
	return true, nil, &routing.ErrNoLiveProvider{
		PromptTokens:  req.EstimatedPromptTokens,
		RequiresTools: req.RequiresTools,
		StartingTier:  req.Profile,
	}
}

// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
// ErrProfilePinConflict) are surfaced as-is — escalating past an explicit
// pin would silently change the caller's intent.
func shouldEscalateOnError(err error) bool {
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return false
	}
	var pinErr *routing.ErrProfilePinConflict
	if errors.As(err, &pinErr) {
		return false
	}
	return true
}

func publicRoutingError(err error, candidates []RouteCandidate) error {
	var modelErr *routing.ErrHarnessModelIncompatible
	if errors.As(err, &modelErr) {
		return withRouteCandidates(&ErrHarnessModelIncompatible{
			Harness:         modelErr.Harness,
			Model:           modelErr.Model,
			SupportedModels: append([]string(nil), modelErr.SupportedModels...),
		}, candidates)
	}
	var profileErr *routing.ErrProfilePinConflict
	if errors.As(err, &profileErr) {
		return withRouteCandidates(&ErrProfilePinConflict{
			Profile:           profileErr.Profile,
			ConflictingPin:    profileErr.ConflictingPin,
			ProfileConstraint: profileErr.ProfileConstraint,
		}, candidates)
	}
	var noProfileErr *routing.ErrNoProfileCandidate
	if errors.As(err, &noProfileErr) {
		return withRouteCandidates(&ErrNoProfileCandidate{
			Profile:           noProfileErr.Profile,
			MissingCapability: noProfileErr.MissingCapability,
			Rejected:          noProfileErr.Rejected,
		}, candidates)
	}
	var noLiveErr *routing.ErrNoLiveProvider
	if errors.As(err, &noLiveErr) {
		return withRouteCandidates(&ErrNoLiveProvider{
			PromptTokens:  noLiveErr.PromptTokens,
			RequiresTools: noLiveErr.RequiresTools,
			StartingTier:  noLiveErr.StartingTier,
		}, candidates)
	}
	var quotaErr *routing.ErrAllProvidersQuotaExhausted
	if errors.As(err, &quotaErr) {
		return withRouteCandidates(&NoViableProviderForNow{
			RetryAfter:         quotaErr.RetryAfter,
			ExhaustedProviders: append([]string(nil), quotaErr.ExhaustedProviders...),
		}, candidates)

