	Time     time.Time
	Metadata map[string]string

	TextDelta        *ServiceTextDeltaData
	ToolCall         *ServiceToolCallData
	ToolResult       *ServiceToolResultData
	Compaction       *ServiceCompactionData
	Progress         *ServiceProgressData
	RoutingDecision  *ServiceRoutingDecisionData
	Stall            *ServiceStallData
	Final            *ServiceFinalData
	Override         *ServiceOverrideData
	RejectedOverride *ServiceOverrideData
}

func DecodeServiceEvent(ev ServiceEvent) (ServiceDecodedEvent, error) {
	decoded := ServiceDecodedEvent{
		Type:     string(ev.Type),
		Sequence: ev.Sequence,
		Time:     ev.Time,
		Metadata: ev.Metadata,
	}
	switch string(ev.Type) {
	case ServiceEventTypeTextDelta:
		var payload ServiceTextDeltaData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.TextDelta = &payload
	case ServiceEventTypeToolCall:
		var payload ServiceToolCallData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.ToolCall = &payload
	case ServiceEventTypeToolResult:
		var payload ServiceToolResultData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.ToolResult = &payload
	case ServiceEventTypeCompaction:
		var payload ServiceCompactionData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.Compaction = &payload
	case ServiceEventTypeProgress:
		var payload ServiceProgressData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.Progress = &payload

		decoded.Progress = &payload
	case ServiceEventTypeRoutingDecision:
		var payload ServiceRoutingDecisionData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.RoutingDecision = &payload
	case ServiceEventTypeStall:
		var payload ServiceStallData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.Stall = &payload
	case ServiceEventTypeFinal:
		var payload ServiceFinalData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.Final = &payload
	case ServiceEventTypeOverride:
		var payload ServiceOverrideData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.Override = &payload
	case ServiceEventTypeRejectedOverride:
		var payload ServiceOverrideData
		if err := decodeServicePayload(ev, &payload); err != nil {
			return decoded, err
		}
		decoded.RejectedOverride = &payload
	default:
		return decoded, fmt.Errorf("decode service event %q: unknown type", ev.Type)
	}
	return decoded, nil
}

func decodeServicePayload(ev ServiceEvent, dst any) error {
	if len(ev.Data) == 0 {
		return fmt.Errorf("decode service event %q: empty data", ev.Type)
	}
	if err := json.Unmarshal(ev.Data, dst); err != nil {
		return fmt.Errorf("decode service event %q: %w", ev.Type, err)
	}
	return nil
}

// DrainExecuteResult is a typed aggregate of one Execute event stream.
type DrainExecuteResult struct {
	Events           []ServiceDecodedEvent
	TextDeltas       []ServiceTextDeltaData
	ToolCalls        []ServiceToolCallData
	ToolResults      []ServiceToolResultData
	Compactions      []ServiceCompactionData
	Progresses       []ServiceProgressData
	Stalls           []ServiceStallData
	RoutingDecision  *ServiceRoutingDecisionData
	Override         *ServiceOverrideData
	RejectedOverride *ServiceOverrideData
	Final            *ServiceFinalData

	FinalStatus    string
	FinalText      string
	Usage          *ServiceFinalUsage
	Warnings       []ServiceFinalWarning
	CostUSD        float64
	SessionLogPath string
	RoutingActual  *ServiceRoutingActual
	TerminalError  string
}

func DrainExecute(ctx context.Context, events <-chan ServiceEvent) (*DrainExecuteResult, error) {
	result := &DrainExecuteResult{}
	for {
		select {
		case <-ctx.Done():
			return result, ctx.Err()
		case ev, ok := <-events:
			if !ok {
				if result.Final == nil {
					return result, errors.New("execute event stream closed without final event")
				}
				return result, nil
			}
			decoded, err := DecodeServiceEvent(ev)
			if err != nil {
				return result, err
			}
			result.append(decoded)
		}
	}
}

func (r *DrainExecuteResult) append(ev ServiceDecodedEvent) {
	r.Events = append(r.Events, ev)
	switch {
	case ev.TextDelta != nil:
		r.TextDeltas = append(r.TextDeltas, *ev.TextDelta)
	case ev.ToolCall != nil:
		r.ToolCalls = append(r.ToolCalls, *ev.ToolCall)
	case ev.ToolResult != nil:
		r.ToolResults = append(r.ToolResults, *ev.ToolResult)
	case ev.Compaction != nil:
		r.Compactions = append(r.Compactions, *ev.Compaction)
	case ev.Progress != nil:
		r.Progresses = append(r.Progresses, *ev.Progress)
	case ev.RoutingDecision != nil:
		r.RoutingDecision = ev.RoutingDecision
	case ev.Override != nil:
		r.Override = ev.Override
	case ev.RejectedOverride != nil:
		r.RejectedOverride = ev.RejectedOverride
	case ev.Stall != nil:
		r.Stalls = append(r.Stalls, *ev.Stall)
	case ev.Final != nil:
		r.Final = ev.Final
		r.FinalStatus = ev.Final.Status
		r.FinalText = ev.Final.FinalText
		r.Usage = ev.Final.Usage
		r.Warnings = ev.Final.Warnings
		r.CostUSD = ev.Final.CostUSD
		r.SessionLogPath = ev.Final.SessionLogPath
		r.RoutingActual = ev.Final.RoutingActual
		r.TerminalError = ev.Final.Error
	}
}

package routehealth

import (
	"sort"
	"strings"
	"sync"
	"time"
)

// DefaultLeaseTTL bounds how long an in-process sticky route lease may live
// without being refreshed.
const DefaultLeaseTTL = 5 * time.Minute

// LeaseKey identifies one sticky lease scope.
type LeaseKey struct {
	StickyKey string
	Provider  string
	Model     string
}

// Lease describes one sticky endpoint assignment.
type Lease struct {
	Key         LeaseKey
	Provider    string
	Endpoint    string
	Model       string
	AcquiredAt  time.Time
	RefreshedAt time.Time
	ExpiresAt   time.Time
}

// LeaseInvalidation records why a lease was removed.
type LeaseInvalidation struct {
	Key        LeaseKey
	Provider   string
	Endpoint   string
	Model      string
	Reason     string
	RecordedAt time.Time
}

// LeaseStore owns in-process sticky route assignments. It is safe for
// concurrent use.
type LeaseStore struct {
	mu            sync.Mutex
	leases        map[LeaseKey]Lease
	invalidations map[LeaseKey]LeaseInvalidation
}

// NewLeaseStore returns an empty lease store.
func NewLeaseStore() *LeaseStore {
	return &LeaseStore{
		leases:        make(map[LeaseKey]Lease),
		invalidations: make(map[LeaseKey]LeaseInvalidation),
	}
}

// NormalizeLeaseKey trims whitespace from the lease dimensions.
func NormalizeLeaseKey(stickyKey, provider, model string) LeaseKey {
	return LeaseKey{
		StickyKey: strings.TrimSpace(stickyKey),
		Provider:  strings.TrimSpace(provider),
		Model:     strings.TrimSpace(model),
	}
}

// Live returns the current lease for key when it has not expired.
func (s *LeaseStore) Live(now time.Time, key LeaseKey) (Lease, bool) {
	if s == nil {
		return Lease{}, false
	}
	now = normalizeLeaseNow(now)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return Lease{}, false
	}
	return lease, true
}

// Acquire stores or refreshes a lease for key.
func (s *LeaseStore) Acquire(now time.Time, ttl time.Duration, key LeaseKey, provider, endpoint, model string) Lease {
	if s == nil {
		return Lease{}
	}
	now = normalizeLeaseNow(now)
	if ttl <= 0 {
		ttl = DefaultLeaseTTL
	}
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)

	lease := Lease{
		Key:         key,
		Provider:    provider,
		Endpoint:    endpoint,
		Model:       model,
		AcquiredAt:  now,
		RefreshedAt: now,
		ExpiresAt:   now.Add(ttl),
	}
	if existing, ok := s.leases[key]; ok {
		if existing.Provider == provider && existing.Endpoint == endpoint && existing.Model == model {
			lease.AcquiredAt = existing.AcquiredAt
		}
	}
	s.leases[key] = lease
	delete(s.invalidations, key)
	return lease
}

// Invalidate removes the lease for key and records the reason.
func (s *LeaseStore) Invalidate(now time.Time, key LeaseKey, reason string) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	now = normalizeLeaseNow(now)
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	lease, ok := s.leases[key]
	if !ok {
		return LeaseInvalidation{}, false
	}
	delete(s.leases, key)
	invalidation := LeaseInvalidation{
		Key:        key,
		Provider:   lease.Provider,
		Endpoint:   lease.Endpoint,
		Model:      lease.Model,
		Reason:     strings.TrimSpace(reason),
		RecordedAt: now,
	}
	s.invalidations[key] = invalidation
	return invalidation, true
}

// InvalidateEndpoint removes every lease for the provider/model scope that
// points at the named endpoint and records the supplied reason.
func (s *LeaseStore) InvalidateEndpoint(now time.Time, provider, endpoint, model, reason string) []LeaseInvalidation {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	endpoint = strings.TrimSpace(endpoint)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	var out []LeaseInvalidation
	for key, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if endpoint != "" && lease.Endpoint != endpoint {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		delete(s.leases, key)
		invalidation := LeaseInvalidation{
			Key:        key,
			Provider:   lease.Provider,
			Endpoint:   lease.Endpoint,
			Model:      lease.Model,
			Reason:     strings.TrimSpace(reason),
			RecordedAt: now,
		}
		s.invalidations[key] = invalidation
		out = append(out, invalidation)
	}
	return out
}

// LiveByScope returns the live leases for provider/model, ordered by sticky
// key for deterministic tests.
func (s *LeaseStore) LiveByScope(now time.Time, provider, model string) []Lease {
	if s == nil {
		return nil
	}
	now = normalizeLeaseNow(now)
	provider = strings.TrimSpace(provider)
	model = strings.TrimSpace(model)

	s.mu.Lock()
	defer s.mu.Unlock()
	s.expireLocked(now)
	if len(s.leases) == 0 {
		return nil
	}
	out := make([]Lease, 0, len(s.leases))
	for _, lease := range s.leases {
		if provider != "" && lease.Provider != provider {
			continue
		}
		if model != "" && lease.Model != model {
			continue
		}
		out = append(out, lease)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Endpoint != out[j].Endpoint {
			return out[i].Endpoint < out[j].Endpoint
		}
		return out[i].Key.StickyKey < out[j].Key.StickyKey
	})
	return out
}

// LeaseCounts returns the live lease count per endpoint for provider/model.
func (s *LeaseStore) LeaseCounts(now time.Time, provider, model string) map[string]int {
	leases := s.LiveByScope(now, provider, model)
	if len(leases) == 0 {
		return nil
	}
	counts := make(map[string]int, len(leases))
	for _, lease := range leases {
		counts[lease.Endpoint]++
	}
	return counts
}

// LastInvalidation returns the most recent invalidation recorded for key.
func (s *LeaseStore) LastInvalidation(key LeaseKey) (LeaseInvalidation, bool) {
	if s == nil {
		return LeaseInvalidation{}, false
	}
	key = NormalizeLeaseKey(key.StickyKey, key.Provider, key.Model)

	s.mu.Lock()
	defer s.mu.Unlock()
	invalidation, ok := s.invalidations[key]
	return invalidation, ok
}

func (s *LeaseStore) expireLocked(now time.Time) {
	for key, lease := range s.leases {
		if lease.ExpiresAt.IsZero() || lease.ExpiresAt.After(now) {
			continue
		}
		delete(s.leases, key)
		s.invalidations[key] = LeaseInvalidation{
			Key:        key,

			Key:        key,
			Provider:   lease.Provider,
			Endpoint:   lease.Endpoint,
			Model:      lease.Model,
			Reason:     "expired",
			RecordedAt: now,
		}
	}
}

func normalizeLeaseNow(now time.Time) time.Time {
	if now.IsZero() {
		return time.Now().UTC()
	}
	return now.UTC()
}

	ProviderCooldowns    map[string]time.Time // by provider name
	CooldownDuration     time.Duration        // 0 = no cooldown enforcement

	// ProviderQuotaExhaustedUntil maps provider name → retry_after time.
	// A provider with retry_after > Now is treated as quota_exhausted and
	// disqualified from candidate selection. The service maintains the
	// per-provider quota state machine and projects it into this map for
	// each routing call.
	ProviderQuotaExhaustedUntil map[string]time.Time
	Now                         time.Time // injected for deterministic testing; default time.Now()
	CatalogResolver             func(ref, surface string) (concreteModel string, ok bool)
	CatalogCandidatesResolver   func(ref, surface string) (concreteModels []string, ok bool)
	ModelEligibility            func(model string) (ModelEligibility, bool)

	// ReasoningResolver returns the catalog's surface_policy reasoning_default
	// for a (profile, surface) pair. When set, buildHarnessCandidates uses it
	// to resolve Reasoning=auto to a concrete level before invoking the
	// capability gate, so candidates that cannot satisfy the resolved level
	// (e.g. an off-only variant under a profile whose surface default is
	// "high") are correctly disqualified instead of slipping through.
	ReasoningResolver func(profile, surface string) (resolved string, ok bool)
}

// EndpointLoad is the routing engine's normalized view of endpoint load for a
// single provider/model tuple.
type EndpointLoad struct {
	LeaseCount           int
	NormalizedLoad       float64
	UtilizationFresh     bool
	UtilizationSaturated bool
}

// ModelEligibility is the routing engine's catalog-power view for one model.
// Unknown or zero-power models are still usable through exact Model pins, but
// are excluded from unpinned automatic routing.
type ModelEligibility struct {
	Power        int
	ExactPinOnly bool
	AutoRoutable bool
}

// candidateInternal carries the engine's intermediate state per (harness, provider, model).
type candidateInternal struct {
	Harness               string
	Provider              string
	EndpointName          string
	Model                 string
	CostClass             string
	CostUSDPer1kTokens    float64
	CostSource            string
	Power                 int
	IsSubscription        bool
	QuotaOK               bool
	QuotaPercentUsed      int
	QuotaStale            bool
	QuotaTrend            string
	SubscriptionOK        bool
	HistoricalSuccessRate float64
	ProviderSuccessRate   float64
	ObservedTokensPerSec  float64
	ObservedLatencyMS     float64
	InCooldown            bool
	ProviderAffinityMatch bool
	ProviderPreference    string
	EndpointLoad          float64
	EndpointLoadFresh     bool
	EndpointSaturated     bool
}

// ProviderModelKey is the metrics key used by routing callers for provider
// performance signals. Endpoint is optional; when empty the key remains
// compatible with older provider:model metrics.
func ProviderModelKey(provider, endpoint, model string) string {
	if endpoint == "" {
		return provider + ":" + model
	}
	return provider + "@" + endpoint + ":" + model
}

// Resolve runs the engine end-to-end and returns a Decision.
//

//
// The engine:
//  1. Enumerates (harness, provider, model) candidates from inputs.
//  2. Applies gating (capability, override, model-pin, surface).
//  3. Scores per profile policy with cooldown demotion + perf bias.
//  4. Sorts viable → score → cost → locality → name.
//  5. Returns the top viable candidate with the full ranked list.
//
// Returns an error only when no viable candidate exists.
func Resolve(req Request, in Inputs) (*Decision, error) {
	if in.Now.IsZero() {
		in.Now = time.Now()
	}

	canonicalHarness := req.Harness
	if canonicalHarness == "local" {
		canonicalHarness = "agent"
	}

	var ranked []rankedCandidate
	for _, h := range in.Harnesses {
		// TestOnly harnesses (script/virtual) only reachable via explicit override.
		if h.TestOnly && canonicalHarness != h.Name {
			continue
		}
		// Automatic profile/tier routing is restricted to harnesses with full
		// coverage. Explicit Harness pins can still use experimental/ad-hoc
		// harnesses.
		if canonicalHarness == "" && !h.AutoRoutingEligible {
			continue
		}
		// Hard harness override: skip non-matching harnesses.
		if canonicalHarness != "" && canonicalHarness != h.Name {
			continue
		}
		entries := buildHarnessCandidates(h, req, in)
		ranked = append(ranked, entries...)
	}

	// Compute scores.
	for i := range ranked {
		ranked[i].out.Score = scorePolicy(req.Profile, ranked[i].internal)
		if ranked[i].out.Eligible {
			ranked[i].out.Reason = fmt.Sprintf("profile=%s; score=%.1f", req.Profile, ranked[i].out.Score)
		}
	}
	neutralCost, hasKnownCost := neutralKnownCost(ranked)

	// Sort: eligible first, then descending score, then cost, then locality,
	// then alphabetical.
	sort.SliceStable(ranked, func(i, j int) bool {
		ei, ej := ranked[i].out.Eligible, ranked[j].out.Eligible
		if ei != ej {
			return ei
		}
		if !ei {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		if ranked[i].out.Score != ranked[j].out.Score {
			return ranked[i].out.Score > ranked[j].out.Score
		}
		if hasKnownCost {
			ci := candidateCostTieValue(ranked[i], neutralCost)
			cj := candidateCostTieValue(ranked[j], neutralCost)
			if ci != cj {
				return ci < cj
			}
		}
		// Locality tiebreak: prefer local cost-class.
		li := costClassRank[ranked[i].internal.CostClass] == 0
		lj := costClassRank[ranked[j].internal.CostClass] == 0
		if li != lj {
			return li
		}
		if sameLocalEndpointGroup(ranked[i].internal, ranked[j].internal) {
			if ranked[i].internal.EndpointSaturated != ranked[j].internal.EndpointSaturated {
				return !ranked[i].internal.EndpointSaturated
			}
			if ranked[i].internal.EndpointLoad != ranked[j].internal.EndpointLoad {
				return ranked[i].internal.EndpointLoad < ranked[j].internal.EndpointLoad
			}
		}
		if ranked[i].out.Harness != ranked[j].out.Harness {
			return ranked[i].out.Harness < ranked[j].out.Harness
		}
		return ranked[i].out.Provider < ranked[j].out.Provider
	})

	out := make([]Candidate, len(ranked))
	for i := range ranked {
		out[i] = ranked[i].out
	}

	if err := explicitPinError(req, in); err != nil {
		return &Decision{Candidates: out}, err
	}

	for i := range out {
		if out[i].Eligible {
			return &Decision{
				Harness:    out[i].Harness,
				Provider:   out[i].Provider,
				Endpoint:   out[i].Endpoint,
				Model:      out[i].Model,
				Reason:     fmt.Sprintf("profile=%s; score=%.1f", req.Profile, out[i].Score),
				Candidates: out,
			}, nil
		}
	}
	if quotaErr := allProvidersQuotaExhaustedError(ranked); quotaErr != nil {
		return &Decision{Candidates: out}, quotaErr
	}
	if requested := requestedModelIntent(req); requested != "" && req.Provider == "" && canonicalHarness == "" && hasLiveDiscoveryCandidates(ranked) {
		return &Decision{Candidates: out}, fmt.Errorf("no live endpoint offers a match for %s", requested)
	}
	if missingCapability := missingProfileCapability(req); missingCapability != "" {
		return &Decision{Candidates: out}, &ErrNoProfileCandidate{
			Profile:           req.Profile,
			MissingCapability: missingCapability,
			Rejected:          len(out),
		}
	}
	return &Decision{Candidates: out}, noViableCandidateError(req, len(out))
}

// allProvidersQuotaExhaustedError returns ErrAllProvidersQuotaExhausted when
// at least one routing candidate was rejected solely because its provider is
// in the quota_exhausted state and no other candidate was eligible. The set
// of otherwise-eligible candidates collapses to those flagged with
// quotaExhaustedRetryAfter (the engine sets this only when the candidate
// passed every other gate). When that set is empty the existing
// no-viable / no-profile-candidate / live-discovery errors describe the
// failure more precisely.
func allProvidersQuotaExhaustedError(ranked []rankedCandidate) error {
	var exhausted []string
	seen := make(map[string]struct{})
	var earliest time.Time
	for _, c := range ranked {
		if c.quotaExhaustedRetryAfter.IsZero() {
			continue
		}

		}
		name := c.out.Provider
		if name == "" {
			name = c.out.Harness
		}
		if _, dup := seen[name]; !dup {
			seen[name] = struct{}{}
			exhausted = append(exhausted, name)
		}
		if earliest.IsZero() || c.quotaExhaustedRetryAfter.Before(earliest) {
			earliest = c.quotaExhaustedRetryAfter
		}
	}
	if len(exhausted) == 0 {
		return nil
	}
	return &ErrAllProvidersQuotaExhausted{
		RetryAfter:         earliest,
		ExhaustedProviders: exhausted,
	}
}

func noViableCandidateError(req Request, rejected int) *NoViableCandidateError {
	return &NoViableCandidateError{
		Rejected: rejected,
		Model:    req.Model,
		Provider: req.Provider,
		Harness:  canonicalHarnessPin(req.Harness),
		MinPower: req.MinPower,
		MaxPower: req.MaxPower,
	}
}

func explicitPinError(req Request, in Inputs) error {
	canonicalHarness := canonicalHarnessPin(req.Harness)
	if req.Profile != "" && (canonicalHarness != "" || req.Model != "") {
		if constraint, ok := explicitProfileConstraint(req.Profile, req.ProviderPreference); ok {
			if canonicalHarness != "" {
				if h, ok := findHarness(in.Harnesses, canonicalHarness); ok && harnessViolatesProfileConstraint(h, constraint) {
					return &ErrProfilePinConflict{
						Profile:           req.Profile,
						ConflictingPin:    "Harness=" + canonicalHarness,
						ProfileConstraint: constraint,
					}
				}
			}
			if req.Model != "" && modelPinViolatesProfileConstraint(req.Model, in, constraint) {
				return &ErrProfilePinConflict{
					Profile:           req.Profile,
					ConflictingPin:    "Model=" + req.Model,
					ProfileConstraint: constraint,
				}
			}
		}
	}

	if canonicalHarness == "" || req.Model == "" {
		return nil
	}
	// Pi can route any provider-pinned model (lmstudio, omlx, openrouter,
	// etc.); the pi CLI owns concrete model validation in that case.
	// Mirrors the bypass in service_execute.go validateExplicitHarnessModel.
	if canonicalHarness == "pi" && req.Provider != "" {
		return nil
	}
	h, ok := findHarness(in.Harnesses, canonicalHarness)
	if !ok || h.SupportedModels == nil || harnessSupportsModel(h.SupportedModels, req.Model) {
		return nil
	}
	return &ErrHarnessModelIncompatible{
		Harness:         canonicalHarness,
		Model:           req.Model,
		SupportedModels: append([]string(nil), h.SupportedModels...),
	}
}

func canonicalHarnessPin(harness string) string {
	if harness == "local" {
		return "agent"
	}
	return harness
}

func findHarness(harnesses []HarnessEntry, name string) (HarnessEntry, bool) {
	for _, h := range harnesses {
		if h.Name == name {
			return h, true
		}
	}
	return HarnessEntry{}, false
}

func harnessSupportsModel(supported []string, model string) bool {
	for _, candidate := range supported {
		if candidate == model {
			return true
		}
	}
	return false
}

func explicitProfileConstraint(profile, providerPreference string) (string, bool) {
	switch providerPreference {
	case ProviderPreferenceLocalOnly:
		return ProviderPreferenceLocalOnly, true
	case ProviderPreferenceSubscriptionOnly:
		return ProviderPreferenceSubscriptionOnly, true
	}
	switch profile {
	case "local", "offline", "air-gapped":
		return ProviderPreferenceLocalOnly, true
	case "smart", "code-smart", "code-high":
		return ProviderPreferenceSubscriptionOnly, true
	default:
		return "", false
	}
}

func harnessViolatesProfileConstraint(h HarnessEntry, constraint string) bool {
	switch constraint {
	case ProviderPreferenceLocalOnly:
		return !h.IsLocal
	case ProviderPreferenceSubscriptionOnly:
		return !h.IsSubscription
	default:
		return false
	}
}

func modelPinViolatesProfileConstraint(model string, in Inputs, constraint string) bool {
	var constrainedCanServe bool
	var outsideCanServe bool
	for _, h := range in.Harnesses {
		if h.TestOnly || !h.AutoRoutingEligible {
			continue
		}
		if !harnessCanServeExactModel(h, model) {
			continue
		}
		if harnessViolatesProfileConstraint(h, constraint) {
			outsideCanServe = true
		} else {
			constrainedCanServe = true
		}
	}
	return !constrainedCanServe && outsideCanServe
}

func harnessCanServeExactModel(h HarnessEntry, model string) bool {
	if len(h.SupportedModels) > 0 && harnessSupportsModel(h.SupportedModels, model) {
		return true
	}
	if h.DefaultModel == model {
		return true
	}
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}
	for _, p := range providers {
		if p.DefaultModel == model {
			return true
		}
		if len(p.DiscoveredIDs) > 0 && FuzzyMatch(model, p.DiscoveredIDs) != "" {
			return true
		}
	}
	return false
}

func missingProfileCapability(req Request) string {
	if req.Profile == "" {
		return ""
	}
	switch req.ProviderPreference {
	case ProviderPreferenceLocalOnly:
		return "local endpoint"
	case ProviderPreferenceSubscriptionOnly:
		return "subscription harness"
	default:
		return ""
	}
}

func requestedModelIntent(req Request) string {
	switch {
	case req.Model != "":
		return req.Model
	case req.ModelRef != "":
		return req.ModelRef
	case req.Profile != "":
		return req.Profile
	default:
		return ""
	}
}

func hasLiveDiscoveryCandidates(candidates []rankedCandidate) bool {
	for _, c := range candidates {
		if c.out.Provider != "" && c.internal.Model == "" {
			return true
		}
		if c.out.Provider != "" && c.out.Reason != "" {
			return true
		}
	}
	return false
}

type rankedCandidate struct {
	out      Candidate
	internal candidateInternal
	// quotaExhaustedRetryAfter is non-zero when this candidate would have been
	// eligible save for its provider being in the quota_exhausted state.
	// Resolve uses this to detect the "all eligible providers quota-exhausted"
	// case and surface ErrAllProvidersQuotaExhausted.
	quotaExhaustedRetryAfter time.Time
}

// buildHarnessCandidates expands one HarnessEntry into 1..N candidates, one
// per (harness, provider, resolved-model) tuple.
func buildHarnessCandidates(h HarnessEntry, req Request, in Inputs) []rankedCandidate {
	caps := Capabilities{
		SupportsTools:      h.SupportsTools,
		SupportedReasoning: h.SupportedReasoning,
		MaxReasoningTokens: h.MaxReasoningTokens,
		SupportedPerms:     h.SupportedPerms,
		ExactPinSupport:    h.ExactPinSupport,
		SupportedModels:    h.SupportedModels,
	}

	if !h.Available {
		return []rankedCandidate{{
			out: Candidate{
				Harness:      h.Name,
				CostSource:   CostSourceUnknown,
				Reason:       "harness not available",
				FilterReason: FilterReasonUnhealthy,
			},
			internal: candidateInternal{Harness: h.Name, CostClass: h.CostClass, CostSource: CostSourceUnknown},
		}}

	ctxWin = p.ContextWindows[model]
}
entryCaps := caps
entryCaps.ContextWindow = ctxWin
entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
if len(p.DiscoveredIDs) > 0 {
	entryCaps.SupportedModels = nil
}

key := ProviderModelKey(p.Name, p.EndpointName, model)
obs := in.ObservedSpeedTPS[key]
if obs == 0 && p.EndpointName != "" {
	obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
}
providerSuccessRate := -1.0
if rate, ok := in.ProviderSuccessRate[key]; ok {
	providerSuccessRate = rate
} else if p.EndpointName != "" {
	if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
		providerSuccessRate = rate
	}
}
latencyMS := in.ObservedLatencyMS[key]
if latencyMS == 0 && p.EndpointName != "" {
	latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
}
power := candidatePower(in.ModelEligibility, model)
endpointLoad := EndpointLoad{}
if in.EndpointLoadResolver != nil {
	loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
	if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
		endpointLoad = resolved
	}
} else if load, ok := in.EndpointLoads[key]; ok {
	endpointLoad = load
}

gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)

eligible := true
var filterReason FilterReason
if reason == "" {
	// Subscription quota is a hard availability gate and must be
	// reported before catalog metadata gates. An exhausted Claude/Codex/
	// Gemini account is never a viable candidate, regardless of whether
	// the resolved model has complete power metadata.
	if h.IsSubscription && !h.SubscriptionOK {
		eligible = false
		reason = h.QuotaReason
		if reason == "" {
			if h.QuotaStale {
				reason = "subscription quota unavailable"
			} else {
				reason = "subscription quota exhausted"
			}
		}
		filterReason = FilterReasonUnhealthy
	} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
		eligible = false
		reason = g
		filterReason = fr
	} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
		eligible = false
		reason = g
		filterReason = fr
	}
} else {
	eligible = false
	// resolveModel rejection — model resolution is a capability
	// mismatch with no specific public category, so fall through
	// to the catch-all.
	filterReason = FilterReasonScoredBelowTop
}

// Hard preference filtering.
if eligible {
	switch req.ProviderPreference {
	case ProviderPreferenceLocalOnly:
		if !h.IsLocal {
			eligible = false
			reason = "preference is local-only"
			filterReason = FilterReasonUnhealthy
		}
	case ProviderPreferenceSubscriptionOnly:
		if !h.IsSubscription {
			eligible = false
			reason = "preference is subscription-only"
			filterReason = FilterReasonUnhealthy
		}
	}
}

if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
	// Hard provider pin: reject every other provider identity, even
	// when a non-pinned candidate would otherwise score higher.
	eligible = false
	reason = fmt.Sprintf("provider override requires %s", req.Provider)
	filterReason = FilterReasonPinMismatch
}

inCooldown := false
if p.Name != "" && p.InCooldown {
	inCooldown = true
} else if p.Name != "" && in.CooldownDuration > 0 {
	if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
		if in.Now.Sub(failedAt) < in.CooldownDuration {
			inCooldown = true
		}
	}
}

// Provider quota-exhausted gate. The state machine lives in the
// service layer; the engine consumes the projected map of
// provider-name → retry_after. Apply only when the candidate would
// otherwise have been eligible — disqualifying an already-rejected
// candidate with a different reason would lose the original signal.
var quotaExhaustedRetryAfter time.Time
if eligible {
	providerKey := candidateProviderIdentity(h, p)
	if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
		if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
			eligible = false
			reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
			filterReason = FilterReasonQuotaExhausted
			quotaExhaustedRetryAfter = retryAfter
		}
	}
}

ci := candidateInternal{
	Harness:               h.Name,
	Provider:              p.Name,
	EndpointName:          p.EndpointName,
	Model:                 model,
	CostClass:             candidateCostClass(h, p),
	CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
	CostSource:            normalizeCostSource(p.CostSource),
	Power:                 power,
	IsSubscription:        h.IsSubscription,
	QuotaOK:               h.QuotaOK,
	QuotaPercentUsed:      h.QuotaPercentUsed,
	QuotaStale:            h.QuotaStale,
	QuotaTrend:            h.QuotaTrend,
	SubscriptionOK:        h.SubscriptionOK,
	HistoricalSuccessRate: histRate,
	ProviderSuccessRate:   providerSuccessRate,
	ObservedTokensPerSec:  obs,
	ObservedLatencyMS:     latencyMS,
	InCooldown:            inCooldown || h.InCooldown,
	ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
	ProviderPreference:    req.ProviderPreference,
	EndpointLoad:          endpointLoad.NormalizedLoad,
	EndpointLoadFresh:     endpointLoad.UtilizationFresh,
	EndpointSaturated:     endpointLoad.UtilizationSaturated,
}
out = append(out, rankedCandidate{
	out: Candidate{
		Harness:            h.Name,
		Provider:           p.Name,
		Endpoint:           p.EndpointName,
		Model:              model,

				Model:              model,
				CostUSDPer1kTokens: p.CostUSDPer1kTokens,
				CostSource:         normalizeCostSource(p.CostSource),
				Power:              power,
				Eligible:           eligible,
				Reason:             reason,
				FilterReason:       filterReason,
				LatencyMS:          latencyMS,
				SuccessRate:        providerSuccessRate,
				CostClass:          candidateCostClass(h, p),
				SpeedTPS:           obs,
				QuotaOK:            h.QuotaOK,
				QuotaPercentUsed:   h.QuotaPercentUsed,
				QuotaTrend:         h.QuotaTrend,
			},
			internal:                 ci,
			quotaExhaustedRetryAfter: quotaExhaustedRetryAfter,
		})
	}
	return out
}

func candidatePower(lookup func(string) (ModelEligibility, bool), model string) int {
	if lookup == nil || model == "" {
		return 0
	}
	eligibility, ok := lookup(model)
	if !ok {
		return 0
	}
	return eligibility.Power
}

func candidateProviderIdentity(h HarnessEntry, p ProviderEntry) string {
	if p.Name != "" {
		return p.Name
	}
	return h.Name
}

func candidateLoadIdentity(h HarnessEntry, p ProviderEntry) (string, string) {
	provider := candidateProviderIdentity(h, p)
	endpoint := p.EndpointName
	if base, ep, ok := strings.Cut(provider, "@"); ok && base != "" {
		provider = base
		if endpoint == "" {
			endpoint = ep
		}
	}
	return provider, endpoint
}

func candidateCostClass(h HarnessEntry, p ProviderEntry) string {
	if p.CostClass != "" {
		return p.CostClass
	}
	return h.CostClass
}

func normalizeCostSource(source string) string {
	switch source {
	case CostSourceCatalog, CostSourceSubscription, CostSourceUserConfig:
		return source
	default:
		return CostSourceUnknown
	}
}

func sameLocalEndpointGroup(a, b candidateInternal) bool {
	if a.Harness == "" || b.Harness == "" || a.Model == "" || b.Model == "" {
		return false
	}
	if a.CostClass != "local" || b.CostClass != "local" {
		return false
	}
	aBase := providerBaseName(a.Provider)
	bBase := providerBaseName(b.Provider)
	if aBase == "" || bBase == "" || aBase != bBase {
		return false
	}
	return a.Model == b.Model

